/* @lc app=leetcode id=3785 lang=kotlin */ class Solution { fun minSwaps(nums: IntArray, forbidden: IntArray): Int = nums.size.let { n -> nums.toList().groupingBy { it }.eachCount().let { cn -> forbidden.toList().groupingBy { it }.eachCount().let { cf -> if ((cn.keys + cf.keys).any { (cn[it] ?: 0) + (cf[it] ?: 0) > n }) -1 else nums.indices.filter { nums[it] == forbidden[it] }.let { bad -> maxOf((bad.size + 1) / 2, bad.groupingBy { nums[it] }.eachCount().values.maxOrNull() ?: 0) } } } } }